def f_x(x, y):
    S = x + y
    T_S = S * (S + 1) // 2
    return T_S + x

count_odd = 0
N = 100
for x in range(N):
    for y in range(N):
        if f_x(x, y) % 2 != 0:
            count_odd += 1
print(f"N for f_x(x, y) = (x+y)(x+y+1)/2 + x is: {count_odd}")
